import torch
import torch.nn as nn
import torch.nn.functional as F



class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, a, b, bias):
        return torch.matmul(a, b) + bias


def get_inputs():
    a = torch.randn(4096, 4096, dtype=torch.float16)
    b = torch.randn(4096, 4096, dtype=torch.float16)
    bias = torch.randn(1, 4096, dtype=torch.float16)
    return [a, b, bias]


def get_init_inputs():
    return []


def run(a, b, bias):
    model = Model()
    device = a.device
    model = model.to(device)
    model.eval()
    with torch.no_grad():
        result = model(a, b, bias)
    return result


def _legacy_gen_inputs(axes, device):
    inputs = get_inputs()
    result = {}
    result['a'] = inputs[0].to(device) if hasattr(inputs[0], 'to') else inputs[0]
    result['b'] = inputs[1].to(device) if hasattr(inputs[1], 'to') else inputs[1]
    result['bias'] = inputs[2].to(device) if hasattr(inputs[2], 'to') else inputs[2]
    return result

def gen_inputs(ctx, device):
    del ctx
    return _legacy_gen_inputs({'M': 4096, 'K': 4096, 'N': 4096}, device)
